use odc::*; use serde_json::Value; use std::{env,fs,path::Path};
fn main(){let a:Vec<String>=env::args().collect();if a.len()<3{eprintln!("Uso: odc info|verify|extract|create|set-meta|remove-meta");std::process::exit(2)}let r=match a[1].as_str(){"info"=>info_file(Path::new(&a[2])).and_then(|i|serde_json::to_string_pretty(&i).map_err(|e|e.to_string())).map(|s|println!("{s}")),"verify"=>{if verify(Path::new(&a[2])){println!("OK");Ok(())}else{Err("INVALIDO".into())}},"extract"=>extract(Path::new(&a[2]),Path::new(&a[3])),"create"=>{let m:Option<Value>=if a.len()>4{Some(serde_json::from_str(&fs::read_to_string(&a[4]).unwrap()).unwrap())}else{None};create_from_file(Path::new(&a[2]),Path::new(&a[3]),m.as_ref(),true)},"set-meta"=>{let m:Value=serde_json::from_str(&fs::read_to_string(&a[3]).unwrap()).unwrap();set_metadata(Path::new(&a[2]),Some(&m))},"remove-meta"=>set_metadata(Path::new(&a[2]),None),_=>Err("comando inválido".into())};if let Err(e)=r{eprintln!("ERRO: {e}");std::process::exit(1)}}
